// Drawn plan and section views of Caliber 08.
//
// These are schematics — the kind of plate drawing a workshop publishes — not
// renderings pretending to be photographs. Geometry is laid out to match how a
// manual-winding movement is actually organised: barrel at one side, the train
// stepping up across the plate, escapement and balance at the other, motion
// work concentric at the centre where the hands come through.
//
// The escape wheel and balance run at Caliber 08's real rate: 5 releases per
// second, 18,000 semi-oscillations per hour. Train speeds are compressed so the
// step-up ratio is visible; the relationship between them is the true part.

const TAU = Math.PI * 2

function ticks(cx, cy, r, n, len, phase = 0) {
  const out = []
  for (let i = 0; i < n; i++) {
    const a = phase + (i / n) * TAU
    const c = Math.cos(a)
    const s = Math.sin(a)
    out.push(`M${(cx + c * (r - len)).toFixed(2)} ${(cy + s * (r - len)).toFixed(2)}L${(cx + c * (r + len * 0.35)).toFixed(2)} ${(cy + s * (r + len * 0.35)).toFixed(2)}`)
  }
  return out.join('')
}

function spokes(cx, cy, r, n, phase = 0) {
  const out = []
  for (let i = 0; i < n; i++) {
    const a = phase + (i / n) * Math.PI
    out.push(`M${(cx - Math.cos(a) * r).toFixed(2)} ${(cy - Math.sin(a) * r).toFixed(2)}L${(cx + Math.cos(a) * r).toFixed(2)} ${(cy + Math.sin(a) * r).toFixed(2)}`)
  }
  return out.join('')
}

function spiral(cx, cy, rStart, rEnd, turns, steps = 260) {
  let d = ''
  for (let i = 0; i <= steps; i++) {
    const t = i / steps
    const a = t * turns * TAU
    const r = rStart + (rEnd - rStart) * t
    const x = (cx + Math.cos(a) * r).toFixed(2)
    const y = (cy + Math.sin(a) * r).toFixed(2)
    d += (i === 0 ? 'M' : 'L') + x + ' ' + y
  }
  return d
}

// Wheel positions. Kept as data so the bridge outline and the energy trace can
// be derived from the same numbers the wheels are drawn from.
const W = {
  barrel: { x: 132, y: 148, r: 64 },
  t1: { x: 224, y: 166, r: 40 },
  t2: { x: 274, y: 228, r: 29 },
