                <li key={l.id} className={layer === l.id ? 'is-held' : undefined} data-reveal>
                  <p className="ln-name">
                    {l.name} <span className="ln-mm">{l.thickness}</span>
                  </p>
                  <p className="ln-note">{l.note}</p>
                </li>
              ))}
            </ul>
          </div>
        </section>

        {/* 04 — rest --------------------------------------------------- */}
        <section id="workshop" className="workshop">
          <div className="workshop-media">
            <Figure
              className="ws-place"
              src="/media/vallee-de-joux.jpg"
              alt="A snow-covered clearing among tall firs at Le Sentier in the Vallée de Joux, Switzerland."
              caption="Le Sentier, Vallée de Joux."
              credit="Nouhailler, CC BY-SA 2.0"
              tall
            />
            <Figure
              className="ws-bench"
              src="/media/staking-set.jpg"
              alt="A watchmaker’s staking set: rows of steel punches standing in a wooden bench block."
              caption="A staking set on the bench."
              credit="dustpuppy, CC BY-SA 2.0"
            />
          </div>

          <div className="workshop-text">
            <div className="sec-head" data-reveal>
              <p className="sec-num">04</p>
              <h2>The workshop</h2>
            </div>
            <ul className="facts">
              {ATELIER.map((a, i) => (
                <li key={a} data-reveal>
                  <span className="fact-mark" aria-hidden="true">{ATELIER_MARKS[i]}</span>
                  <p>{a}</p>
                </li>
              ))}
            </ul>
          </div>
        </section>

        {/* 05 — prove: the printed record ----------------------------- */}
        <section id="record" className="record">
          <div className="doc" data-reveal>
            <header className="doc-head">
              <div>
                <p className="doc-kicker">Aubry &amp; Vent · Vallée de Joux</p>
                <h2>Specification</h2>
              </div>
              <p className="doc-ref">Ref. Caliber 08</p>
            </header>

            <dl className="doc-rows">
              {SPECS.map(([k, v]) => (
                <div
                  key={k}
                  className={'doc-row' + (k === 'Components' || k === 'Finishing hours' ? ' is-lead' : '')}
                >
                  <dt>{k}</dt>
                  <dd>{v}</dd>
                </div>
              ))}
            </dl>

            <p className="doc-foot">
              A timing record for the individual movement is drawn up after twenty-one days on test and
              ships with it.
            </p>
          </div>
        </section>

        {/* 06 — compare ------------------------------------------------ */}
        <section id="finishes" className="finishes">
          <div className="sec-head" data-reveal>
            <p className="sec-num">06</p>
            <h2>Three finishes</h2>
            <p className="sec-lede">
              The same caliber, finished three ways. Prices are for the movement alone; casing is
              arranged separately.
            </p>
          </div>

          <ul className="finish-list" role="list">
            {CONFIGURATIONS.map((c) => {
              const isOn = config === c.id
              return (
                <li key={c.id} data-config={c.id} className={'finish' + (isOn ? ' is-chosen' : '')} data-reveal>
                  <div className="finish-plate" data-finish={c.id} aria-hidden="true">
                    <MovementPlate id={'fin-' + c.id} running={false} focus={null} />
                  </div>

                  <div className="finish-body">
                    <h3>{c.name}</h3>
                    <p className="finish-desc">{c.finish}</p>
                    <dl className="finish-facts">
                      <div>
                        <dt>Price</dt>
                        <dd className="price">CHF {chf(c.price)}</dd>
                      </div>
                      <div>
                        <dt>Delivery</dt>
                        <dd>{c.lead}</dd>
                      </div>
                      <div>
                        <dt>Allocation</dt>
                        <dd className="rem">{c.remaining} of the run still unallocated</dd>
                      </div>
                    </dl>
                    <button
                      type="button"
                      className={'btn ' + (isOn ? 'btn-solid' : 'btn-line')}
                      onClick={() => chooseFinish(c.id)}
                      aria-pressed={isOn}
                    >
                      {isOn ? 'Chosen — this finish' : 'Choose this finish'}
                    </button>
                  </div>
                </li>
              )
            })}
          </ul>
        </section>

        {/* 07 — decide ------------------------------------------------- */}
        <section id="reserve" className="reserve">
          <div className="sec-head" data-reveal>
            <p className="sec-num">07</p>
            <h2>Reserve a movement</h2>
            <p className="sec-lede">
              Reservations are not binding and no payment is taken now. We will write once, with the
              timing record of the movement allocated to you.
            </p>
          </div>

          <div className="reserve-body">
            <div className={'slip' + (reserved ? ' is-stamped' : '')} data-reveal>
              <p className="slip-kicker">Reservation slip</p>
              {chosen ? (
                <>
                  <p className="slip-finish">{chosen.name}</p>
                  <p className="slip-price">CHF {chf(chosen.price)}</p>
                  <dl className="slip-rows">
                    <div>
                      <dt>Delivery</dt>
                      <dd>{chosen.lead}</dd>
                    </div>
                    <div>
                      <dt>Allocation</dt>
                      <dd>{chosen.remaining} unallocated</dd>
                    </div>
                    <div>
                      <dt>Payment</dt>
                      <dd>None taken</dd>
                    </div>
                  </dl>
                </>
              ) : (
                <div className="slip-empty">
                  <p>No finish chosen yet.</p>
                  <button type="button" className="btn btn-line" onClick={() => goTo('finishes')}>
                    See the three finishes
                  </button>
                </div>
              )}
              {reserved && <p className="slip-stamp" aria-hidden="true">Held</p>}
            </div>

            {reserved ? (
              <p className="confirm" role="status">
                Reserved. {name}, we have held one {chosen.name} movement at CHF {chf(chosen.price)} and
                will write to {email}. {chosen.lead}.
              </p>
            ) : (
              <form onSubmit={handleSubmit} noValidate>
                <div className="field">
                  <label htmlFor="config">Which finish?</label>
                  <select
                    id="config"
                    name="config"
                    required
                    value={config}
                    onChange={(e) => setConfig(e.target.value)}
                  >
                    <option value="">Choose a finish</option>
                    {CONFIGURATIONS.map((c) => (
                      <option key={c.id} value={c.id}>
                        {c.name} — CHF {chf(c.price)}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="field">
                  <label htmlFor="name">Your name</label>
                  <input
                    id="name"
                    name="name"
                    type="text"
                    required
                    autoComplete="name"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                  />
                </div>

                <div className="field">
                  <label htmlFor="email">Email</label>
                  <input
                    id="email"
                    name="email"
                    type="email"
                    required
                    autoComplete="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                  />
                </div>

                {touched && (!name || !email || !config) && (
                  <p className="form-note" role="alert">
                    A finish, a name, and an email are needed before we can hold one.
                  </p>
                )}

                <button type="submit" className="btn btn-solid btn-wide">
                  Reserve a movement
                </button>
                <p className="form-fine">Not binding. No payment is taken now.</p>
              </form>
            )}
          </div>
        </section>
      </main>

      <footer className="foot">
        <div className="foot-top">
          <p className="foot-mark">Aubry &amp; Vent</p>
          <p className="foot-contact">
            Enquiries: <a href="mailto:atelier@aubryvent.ch">atelier@aubryvent.ch</a>
          </p>
          <p className="foot-links">Servicing. Provenance. Terms of reservation.</p>
        </div>
        <div className="foot-credits">
          <p className="credits-head">Photography</p>
          <ul>
            {CREDITS.map((c) => (
              <li key={c.file}>
                <a href={c.href} rel="noreferrer noopener" target="_blank">{c.what}</a>
                <span> — {c.who}, {c.licence}</span>
              </li>
            ))}
          </ul>
          <p className="credits-note">
            Reference photography of mechanical watchmaking. Plate and layer drawings are schematics of
            Caliber 08.
          </p>
        </div>
        <p className="foot-legal">Aubry &amp; Vent. Caliber 08. © 2026.</p>
      </footer>
    </div>
  )
}

/* ===================================================================
   Caliber 08 — Aubry & Vent

   Colour is sampled off the movement itself: the cool graphite of the
   inside of a case, German silver, brass train wheels, ruby bearings,
   and the one blue that exists in a watch because a screw was heated
   to it. Type is the two documents a movement travels with — the
   engraved plate (Newsreader) and the timing record (IBM Plex Mono).
   =================================================================== */

:root {
  --ink: #0a0c0f;
  --ink-2: #0e1116;
  --panel: #14181f;
  --panel-2: #1a1f27;

  --silver: #e6e9ec;
  --steel: #9ba4ae;
  --dim: #69727d;

  --brass: #c49a55;
  --brass-dim: #8a6c3c;
  --blued: #6c93d6;
  --ruby: #c4566f;

  --paper: #e9e3d6;
  --paper-2: #ded7c8;
  --paper-ink: #16140f;
  --paper-dim: #6a6355;

  --line: rgba(214, 223, 233, 0.13);
  --line-soft: rgba(214, 223, 233, 0.07);
  --line-strong: rgba(214, 223, 233, 0.26);

  --serif: 'Newsreader', 'Iowan Old Style', Georgia, 'Times New Roman', serif;
  --mono: 'IBM Plex Mono', ui-monospace, 'SFMono-Regular', Menlo, monospace;

  --gut: clamp(20px, 4.5vw, 68px);
  --rail: 0px;

  --t: 150ms cubic-bezier(0.32, 0.72, 0.3, 1);
  --t-slow: 620ms cubic-bezier(0.22, 0.68, 0.24, 1);
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--ink);
  color: var(--silver);
  font-family: var(--serif);
  font-size: 17px;
  line-height: 1.62;
  font-synthesis-weight: none;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
h1, h2, h3 { margin: 0; font-weight: 300; letter-spacing: -0.015em; }
p { margin: 0; }
ul, ol, dl, dd { margin: 0; padding: 0; }
li { list-style: none; }

::selection { background: rgba(108, 147, 214, 0.32); }

/* ------------------------------------------------- interaction baseline */
/* One grammar for the whole route: 150ms, colour + a rule that grows from
   the left + one pixel of press. Nothing here is trying to be interesting. */

button, select, input, a { font: inherit; color: inherit; }

a {
  color: var(--silver);
  text-decoration: none;
  background-image: linear-gradient(var(--blued), var(--blued));
  background-size: 0% 1px;
  background-position: 0 100%;
  background-repeat: no-repeat;
  transition: background-size var(--t), color var(--t);
}
a:hover { background-size: 100% 1px; }

:focus-visible {
  outline: 2px solid var(--blued);
  outline-offset: 3px;
  border-radius: 1px;
}

.skip {
  position: fixed;
  top: 8px;
  left: 8px;
  z-index: 200;
  padding: 10px 16px;
  background: var(--panel);
  border: 1px solid var(--line-strong);
  transform: translateY(-160%);
  transition: transform var(--t);
}
.skip:focus { transform: none; }

.btn {
  --btn-fg: var(--silver);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 46px;
  padding: 0 22px;
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 400;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--btn-fg);
  background: transparent;
  border: 1px solid var(--line-strong);
  border-radius: 2px;
  cursor: pointer;
  transition: background var(--t), border-color var(--t), color var(--t), transform var(--t);
}
.btn:hover { border-color: var(--blued); color: #fff; background: rgba(108, 147, 214, 0.09); }
.btn:active { transform: translateY(1px); }
.btn-solid {
  background: var(--silver);
  color: var(--ink);
  border-color: var(--silver);
}
.btn-solid:hover { background: #fff; color: var(--ink); border-color: #fff; }
.btn-quiet { min-height: 38px; padding: 0 15px; font-size: 11px; }
.btn-wide { width: 100%; }

/* regional entrance */
[data-reveal] {
  opacity: 0;
  transform: translateY(14px);
  transition: opacity var(--t-slow), transform var(--t-slow);
}
[data-reveal].is-in { opacity: 1; transform: none; }

.page[data-reduced='yes'] [data-reveal] { opacity: 1; transform: none; transition: none; }

/* --------------------------------------------------------------- chrome */

.topbar {
  position: sticky;
  top: 0;
  z-index: 60;
  background: rgba(10, 12, 15, 0.82);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--line-soft);
}
.topbar-in {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 12px var(--gut);
  padding-left: calc(var(--gut) + var(--rail));
}
.mark { background: none; display: flex; flex-direction: column; line-height: 1.1; }
.mark-name { font-size: 17px; letter-spacing: 0.03em; }
.mark-sub {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--dim);
}
.topbar-ident {
  flex: 1;
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--dim);
  text-align: center;
}
.topbar-right { display: flex; align-items: center; gap: 18px; }
.allocation {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--steel);
  white-space: nowrap;
}
.allocation strong { color: var(--ruby); font-weight: 500; }

/* left section index — orientation, and the only navigation on the route */
.index { display: none; }

@media (min-width: 1180px) {
  :root { --rail: 172px; }
  .index {
    display: block;
    position: fixed;
    top: 50%;
    left: 28px;
    transform: translateY(-50%);
    z-index: 55;
  }
  .index ol { display: flex; flex-direction: column; gap: 2px; }
  .index button {
    display: flex;
    align-items: baseline;
    gap: 12px;
    width: 148px;
    padding: 5px 0 5px 10px;
    background: none;
    border: 0;
    border-left: 1px solid var(--line);
    text-align: left;
    cursor: pointer;
    color: var(--dim);
    transition: color var(--t), border-color var(--t), padding-left var(--t);
  }
  .index button:hover { color: var(--silver); border-color: var(--blued); padding-left: 16px; }
  .index button.is-active { color: var(--silver); border-color: var(--brass); }
  .index .num { font-family: var(--mono); font-size: 10px; letter-spacing: 0.1em; }
  .index .lbl { font-size: 14px; }
}

/* ------------------------------------------------------- shared section */

main { display: block; }

section {
  padding-left: calc(var(--gut) + var(--rail));
  padding-right: var(--gut);
}

.sec-head { max-width: 46ch; }
.sec-num {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.28em;
  color: var(--brass-dim);
  margin-bottom: 18px;
}
.sec-head h2 {
  font-size: clamp(30px, 4.4vw, 54px);
  line-height: 1.06;
  letter-spacing: -0.025em;
}
.sec-lede {
  margin-top: 16px;
  color: var(--steel);
  font-size: clamp(16px, 1.35vw, 19px);
  max-width: 42ch;
}

.eyebrow {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--brass);
}

/* ---------------------------------------------------------------- plate */
/* The drawn plan of the movement. Shared by the hero, the power path and
   the three finishes, restyled each time rather than repeated. */

.plate {
  width: 100%;
  height: auto;
  overflow: visible;
  --c-line: rgba(198, 210, 224, 0.5);
  --c-fine: rgba(198, 210, 224, 0.26);
  --c-wheel: var(--brass);
  --c-jewel: var(--ruby);
  --c-blue: var(--blued);
  --face-op: 1;
}
.plate * { vector-effect: non-scaling-stroke; }

.pl-ground > circle:first-child { opacity: var(--face-op); }
.pl-grain line { stroke: rgba(255, 255, 255, 0.045); stroke-width: 1; }
.pl-rim { fill: none; stroke: var(--c-line); stroke-width: 1.2; }
.pl-rim-inner { fill: none; stroke: var(--c-fine); stroke-width: 0.8; stroke-dasharray: 2 4; }
.pl-stem { stroke: var(--c-line); stroke-width: 3; }
.pl-crown { fill: #1c222b; stroke: var(--c-line); stroke-width: 1; }
.pl-crown-knurl { stroke: var(--c-fine); stroke-width: 1; }

.pl-bridge {
  fill: rgba(255, 255, 255, 0.035);
  stroke: var(--c-fine);
  stroke-width: 1;
}

.pt { transition: opacity 420ms ease, filter 420ms ease; }

/* motion work + hands */
.mw-ring { fill: none; stroke: var(--c-fine); stroke-width: 0.9; }
.mw-teeth { stroke: var(--c-fine); stroke-width: 0.7; }
.hand { stroke: var(--c-blue); stroke-width: 2.4; stroke-linecap: round; opacity: 0.85; }
.hand-m { stroke-width: 1.8; }
.hand-boss { fill: var(--c-blue); }

/* mainspring */
.ms-coil { fill: none; stroke: var(--c-line); stroke-width: 1.1; }
.ms-arbor { fill: #232a34; stroke: var(--c-line); stroke-width: 1; }

/* barrel */
.br-wall { fill: none; stroke: var(--c-line); stroke-width: 1.4; }
.br-teeth { stroke: var(--c-fine); stroke-width: 1; }
.br-ratchet { fill: rgba(196, 154, 85, 0.1); stroke: var(--c-wheel); stroke-width: 1; }
.br-ratchet-teeth { stroke: var(--c-wheel); stroke-width: 1.2; }
.br-stopwork { fill: none; stroke: var(--c-blue); stroke-width: 1.6; stroke-linecap: round; }
.br-click { fill: var(--c-blue); }

/* train */
.wh-body { fill: rgba(196, 154, 85, 0.07); stroke: var(--c-wheel); stroke-width: 1; }
.wh-teeth { stroke: var(--c-wheel); stroke-width: 0.9; }
.wh-spoke { stroke: var(--c-wheel); stroke-width: 0.9; opacity: 0.75; }
.wh-arbor { fill: #20262f; stroke: var(--c-line); stroke-width: 0.8; }
.wh-jewel { fill: var(--c-jewel); }

/* escapement */
.esc-body { fill: rgba(196, 154, 85, 0.08); stroke: var(--c-wheel); stroke-width: 1; }
.esc-teeth { stroke: var(--c-wheel); stroke-width: 1.3; }
.esc-spoke { stroke: var(--c-wheel); stroke-width: 0.9; }
.esc-arbor { fill: #20262f; stroke: var(--c-line); stroke-width: 0.8; }
.lv-body, .lv-fork { fill: none; stroke: var(--c-line); stroke-width: 2; stroke-linecap: round; }
.lv-pivot { fill: #20262f; stroke: var(--c-line); stroke-width: 1; }
.lv-pallet { fill: var(--c-jewel); }

/* balance */
.bl-cock { fill: none; stroke: var(--c-line); stroke-width: 7; stroke-linecap: round; opacity: 0.5; }
.bl-rim { fill: none; stroke: var(--c-line); stroke-width: 3.4; }
.bl-rim-in { fill: none; stroke: var(--c-fine); stroke-width: 0.8; }
.bl-arm { stroke: var(--c-line); stroke-width: 2.4; }
.bl-weight { fill: #262e39; stroke: var(--c-line); stroke-width: 1.2; }
.bl-hairspring { fill: none; stroke: var(--c-blue); stroke-width: 0.9; opacity: 0.9; }
.bl-jewel { fill: var(--c-jewel); }

/* the energy trace */
.pl-trace {
  fill: none;
  stroke: var(--c-blue);
  stroke-width: 1.1;
  stroke-dasharray: 3 9;
  opacity: 0.14;
  transition: opacity 420ms ease;
}
.plate[data-focus]:not([data-focus='none']) .pl-trace { opacity: 0.6; }

/* focus: one stage lifts, the rest fall back to hairlines */
.plate[data-focus]:not([data-focus='none']) .pt { opacity: 0.14; }
.plate[data-focus='mainspring'] .pt-mainspring,
.plate[data-focus='barrel'] .pt-barrel,
.plate[data-focus='train'] .pt-train,
.plate[data-focus='escapement'] .pt-escapement,
.plate[data-focus='balance'] .pt-balance,
.plate[data-focus='hands'] .pt-hands {
  opacity: 1;
  filter: drop-shadow(0 0 9px rgba(196, 154, 85, 0.35));
}

/* motion: the movement's own rate, not an easing curve someone liked */
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes escStep { to { transform: rotate(24deg); } }
@keyframes balSwing { from { transform: rotate(-142deg); } to { transform: rotate(142deg); } }
@keyframes lvRock { from { transform: rotate(-7deg); } to { transform: rotate(7deg); } }
@keyframes hsBreathe { from { transform: scale(1); } to { transform: scale(0.93); } }
@keyframes traceFlow { to { stroke-dashoffset: -48; } }

.plate[data-running='yes'] .wh {
  transform-origin: var(--ox) var(--oy);
  animation: spin var(--spin) linear infinite;
}
.plate[data-running='yes'] .ms-coil {
  transform-origin: 132px 148px;
  animation: spin 34s linear infinite;
}
.plate[data-running='yes'] .esc-wheel {
  transform-origin: 292px 306px;
  animation: escStep 0.2s steps(1, end) infinite;
}
.plate[data-running='yes'] .bl-wheel {
  transform-origin: 164px 302px;
  animation: balSwing 0.2s ease-in-out infinite alternate;
}
.plate[data-running='yes'] .bl-hairspring {
  transform-origin: 164px 302px;
  animation: hsBreathe 0.2s ease-in-out infinite alternate;
}
.plate[data-running='yes'] .esc-lever {
  transform-origin: 252px 323px;
  animation: lvRock 0.2s ease-in-out infinite alternate;
}
.plate[data-running='yes'] .pl-trace { animation: traceFlow 2.6s linear infinite; }

/* ----------------------------------------------------------------- hero */

.hero {
  display: grid;
  grid-template-columns: minmax(0, 1.02fr) minmax(0, 0.98fr);
  gap: clamp(28px, 5vw, 76px);
  align-items: center;
  min-height: calc(100vh - 63px);
  padding-top: clamp(48px, 7vh, 92px);
  padding-bottom: clamp(40px, 6vh, 72px);
  position: relative;
}
.hero::after {
  content: '';
  position: absolute;
  left: calc(var(--gut) + var(--rail));
  right: var(--gut);
  bottom: 0;
  height: 1px;
  background: var(--line-soft);
}

.hero h1 {
  margin: 26px 0 0;
  display: flex;
  align-items: baseline;
  gap: 0.16em;
  font-size: clamp(64px, 12.5vw, 172px);
  line-height: 0.86;
  letter-spacing: -0.05em;
  font-weight: 200;
}
.h1-num {
  font-family: var(--mono);
  font-weight: 300;
  font-size: 0.66em;
  letter-spacing: -0.02em;
  color: var(--brass);
}
.hero-lede {
  margin-top: 28px;
  max-width: 30ch;
  font-size: clamp(19px, 1.7vw, 25px);
  line-height: 1.42;
  color: var(--silver);
}
.hero-sentence {
  margin-top: 22px;
  padding-top: 22px;
  border-top: 1px solid var(--line);
  max-width: 44ch;
  color: var(--steel);
  font-size: 16px;
  line-height: 1.68;
}
.hero-actions { margin-top: 34px; display: flex; flex-wrap: wrap; gap: 12px; }

.hero-plate { position: relative; }
.hero-plate .plate { filter: drop-shadow(0 34px 60px rgba(0, 0, 0, 0.6)); }
.plate-legend {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  margin-top: 18px;
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--dim);
}

/* --------------------------------------------------- photographic band */

.band { position: relative; margin: 0; }
.band img {
  width: 100%;
  height: clamp(220px, 40vh, 380px);
  object-fit: cover;
  object-position: 50% 46%;
  filter: saturate(0.72) contrast(1.06) brightness(0.82);
}
.band::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, rgba(10, 12, 15, 0.9), rgba(10, 12, 15, 0.12) 42%, rgba(10, 12, 15, 0.92));
  pointer-events: none;
}
.band-caption {
  position: absolute;
  left: calc(var(--gut) + var(--rail));
  bottom: 18px;
  z-index: 2;
  display: flex;
  flex-direction: column;
  gap: 3px;
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.09em;
  color: var(--steel);
}
.credit { color: var(--dim); font-size: 10px; letter-spacing: 0.11em; }

/* ----------------------------------------------------------- 02 · path */

.path { padding-top: clamp(72px, 11vh, 132px); padding-bottom: clamp(72px, 11vh, 132px); }
.path-body {
  margin-top: clamp(40px, 6vw, 76px);
  display: grid;
  grid-template-columns: minmax(0, 0.92fr) minmax(0, 1.08fr);
  gap: clamp(32px, 5vw, 80px);
  align-items: start;
}
.path-plate-sticky { position: sticky; top: 110px; }
.path-plate .plate { filter: drop-shadow(0 26px 50px rgba(0, 0, 0, 0.55)); }

.path-readout {
  margin-top: 22px;
  padding-top: 16px;
  border-top: 1px solid var(--line);
  display: grid;
  gap: 5px;
}
.path-readout-num { font-family: var(--mono); font-size: 11px; letter-spacing: 0.22em; color: var(--brass); }
.path-readout-name { font-size: 21px; }
.path-readout-fig { font-family: var(--mono); font-size: 12px; letter-spacing: 0.04em; color: var(--steel); }

.stages { display: grid; }
.stage {
  position: relative;
  padding: 26px 0 30px 62px;
  border-top: 1px solid var(--line-soft);
}
.stage::before {
  content: '';
  position: absolute;
  left: 17px;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--line);
}
.stage:first-child::before { top: 34px; }
.stage:last-child::before { bottom: auto; height: 34px; }

.stage-hit {
  display: flex;
  align-items: baseline;
  gap: 16px;
  width: 100%;
  margin-left: -62px;
  padding: 0 0 0 62px;
  background: none;
  border: 0;
  text-align: left;
  cursor: pointer;
}
.stage-num {
  position: absolute;
  left: 0;
  width: 35px;
  text-align: left;
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  color: var(--dim);
  transition: color var(--t);
}
.stage-name {
  font-size: clamp(22px, 2.5vw, 31px);
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: var(--steel);
  transition: color var(--t);
}
.stage-mark {
  position: absolute;
  left: 11px;
  top: 32px;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  border: 1px solid var(--line-strong);
  background: var(--ink);
  transition: background var(--t), border-color var(--t), transform var(--t);
}
.stage-hit:hover .stage-name { color: var(--silver); }
.stage-hit:hover .stage-mark { border-color: var(--blued); }

.stage.is-live .stage-name { color: var(--silver); }
.stage.is-live .stage-num { color: var(--brass); }
.stage.is-live .stage-mark { background: var(--brass); border-color: var(--brass); transform: scale(1.15); }
.stage.is-live::before { background: linear-gradient(var(--brass-dim), var(--line)); }

.stage-detail {
  margin-top: 12px;
  max-width: 48ch;
  color: var(--steel);
  transition: color var(--t);
}
.stage.is-live .stage-detail { color: #c8cfd7; }
.stage-figure {
  margin-top: 14px;
  font-family: var(--mono);
  font-size: clamp(13px, 1.15vw, 15px);
  letter-spacing: 0.02em;
  color: var(--brass);
}

.stage-photo { margin: 22px 0 0; max-width: 420px; }
.plate-photo-frame {
  overflow: hidden;
  border: 1px solid var(--line);
  background: var(--panel);
}
.plate-photo img {
  width: 100%;
  height: 190px;
  object-fit: cover;
  filter: saturate(0.68) contrast(1.05) brightness(0.86);
  transition: filter var(--t-slow), transform var(--t-slow);
}
.plate-photo-frame.is-tall img { height: clamp(280px, 42vh, 460px); }
.plate-photo:hover img { filter: saturate(0.85) contrast(1.05) brightness(0.98); transform: scale(1.02); }
.plate-photo figcaption {
  display: flex;
  flex-direction: column;
  gap: 3px;
  margin-top: 10px;
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: 0.07em;
  color: var(--steel);
}

/* --------------------------------------------------------- 03 · layers */

.layers {
  padding-top: clamp(72px, 11vh, 132px);
  padding-bottom: clamp(72px, 11vh, 132px);
  border-top: 1px solid var(--line-soft);
  background:
    radial-gradient(120% 80% at 62% 45%, rgba(108, 147, 214, 0.08), transparent 62%),
    var(--ink-2);
}
.layers-body {
  --explode: 0;
  margin-top: clamp(36px, 5vw, 68px);
  display: grid;
  grid-template-columns: 200px minmax(0, 1fr) minmax(0, 0.86fr);
  gap: clamp(24px, 4vw, 60px);
  align-items: center;
}

.stack { position: relative; aspect-ratio: 1 / 0.92; }
.stack-layer {
  position: absolute;
  inset: 0;
  z-index: calc(10 - var(--i));
  transform:
    rotateX(58deg) rotateZ(-32deg)
    translateZ(calc((1.5 - var(--i)) * var(--explode) * 78px));
  transform-origin: 50% 55%;
  transition: opacity 380ms ease, filter 380ms ease;
  will-change: transform;
}
.stack-layer .lp { width: 100%; height: auto; overflow: visible; }
.stack-layer.is-back { opacity: 0.2; }
.stack-layer.is-held { filter: drop-shadow(0 0 16px rgba(196, 154, 85, 0.45)); }
.layers-body[data-isolated='yes'] { --explode: 1; }

.lp-face { fill: #171c23; }
.lp-face-cut { fill: #1b212a; }
.lp-edge { fill: none; stroke: rgba(214, 223, 233, 0.42); stroke-width: 1.4; }
.lp-line { fill: none; stroke: rgba(214, 223, 233, 0.2); stroke-width: 1; }
.lp-tick { stroke: rgba(214, 223, 233, 0.24); stroke-width: 1; }
.lp-post { fill: var(--blued); }
.lp-hole { fill: #0a0c0f; stroke: rgba(214, 223, 233, 0.3); stroke-width: 1; }
.lp-frost circle { fill: rgba(255, 255, 255, 0.075); }
.lp-jewel { fill: rgba(196, 86, 111, 0.85); stroke: rgba(214, 223, 233, 0.4); stroke-width: 1; }
.lp-screw { fill: #2a3550; stroke: var(--blued); stroke-width: 1.2; }
.lp-stemline { stroke: rgba(214, 223, 233, 0.4); stroke-width: 2.5; }
.lp-anglage { fill: none; stroke: rgba(233, 240, 248, 0.75); stroke-width: 1.6; }
.stack-layer .lp * { vector-effect: non-scaling-stroke; }

.scale-cap,
.scale-total {
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--dim);
}
.scale-total {
  display: flex;
  justify-content: space-between;
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px solid var(--line);
  color: var(--steel);
}
.scale-bars { margin-top: 14px; display: grid; gap: 4px; }
.scale-bars li { height: calc(var(--mm) * 46px); }
.scale-bars button {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 2px;
  width: 100%;
  height: 100%;
  padding: 0 12px;
  background: rgba(255, 255, 255, 0.035);
  border: 1px solid var(--line);
  border-left: 2px solid var(--line-strong);
  border-radius: 1px;
  text-align: left;
  cursor: pointer;
  transition: background var(--t), border-color var(--t), transform var(--t);
}
.scale-bars button:hover,
.scale-bars button.is-held {
  background: rgba(196, 154, 85, 0.12);
  border-left-color: var(--brass);
  transform: translateX(3px);
}
.scale-name { font-size: 13px; line-height: 1.15; color: var(--silver); }
.scale-mm { font-family: var(--mono); font-size: 11px; color: var(--brass); }

.layer-notes { display: grid; gap: 2px; }
.layer-notes li {
  padding: 16px 18px;
  border-left: 1px solid var(--line);
  transition: background var(--t), border-color var(--t);
}
.layer-notes li.is-held { background: rgba(196, 154, 85, 0.07); border-left-color: var(--brass); }
.ln-name { font-size: 17px; display: flex; justify-content: space-between; gap: 14px; }
.ln-mm { font-family: var(--mono); font-size: 12px; color: var(--brass); letter-spacing: 0.04em; }
.ln-note { margin-top: 5px; color: var(--steel); font-size: 15px; line-height: 1.55; }

/* ------------------------------------------------------- 04 · workshop */

.workshop {
  display: grid;
  grid-template-columns: minmax(0, 0.94fr) minmax(0, 1.06fr);
  gap: clamp(30px, 5vw, 76px);
  align-items: center;
  padding-top: clamp(72px, 11vh, 132px);
  padding-bottom: clamp(72px, 11vh, 132px);
  border-top: 1px solid var(--line-soft);
}
.workshop-media { display: grid; gap: 18px; grid-template-columns: 1fr 0.62fr; align-items: end; }
.ws-place { grid-column: 1 / -1; }
.ws-bench { grid-column: 1 / 2; }
.workshop-media::after {
  content: '';
  grid-column: 2 / 3;
  height: 1px;
}
.facts { margin-top: 30px; display: grid; }
.facts li {
  display: grid;
  grid-template-columns: 82px minmax(0, 1fr);
  gap: 20px;
  align-items: baseline;
  padding: 18px 0;
  border-top: 1px solid var(--line-soft);
}
.facts li:last-child { border-bottom: 1px solid var(--line-soft); }
.fact-mark {
  font-family: var(--mono);
  font-size: clamp(22px, 2.4vw, 30px);
  font-weight: 300;
  letter-spacing: -0.02em;
  color: var(--brass);
  line-height: 1;
}
.facts p { color: var(--steel); font-size: 16px; line-height: 1.62; }

/* --------------------------------------------------------- 05 · record */
/* The one light section on the route: the specification as the printed
   document it actually is. */

.record {
  background: linear-gradient(180deg, var(--paper) 0%, var(--paper-2) 100%);
  color: var(--paper-ink);
  padding-top: clamp(64px, 9vh, 108px);
  padding-bottom: clamp(64px, 9vh, 108px);
}
.doc {
  max-width: 1000px;
  margin: 0 auto;
  padding: clamp(28px, 4vw, 56px);
  background: rgba(255, 255, 255, 0.42);
  border: 1px solid rgba(22, 20, 15, 0.16);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.6) inset;
}
.doc-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  padding-bottom: 20px;
  border-bottom: 1.5px solid rgba(22, 20, 15, 0.5);
}
.doc-kicker {
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--paper-dim);
  margin-bottom: 8px;
}
.doc-head h2 { font-size: clamp(28px, 3.6vw, 44px); color: var(--paper-ink); letter-spacing: -0.025em; }
.doc-ref {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--paper-dim);
  white-space: nowrap;
}

.doc-rows { margin-top: 4px; columns: 2; column-gap: 56px; }
.doc-row {
  break-inside: avoid;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 18px;
  padding: 13px 0;
  border-bottom: 1px solid rgba(22, 20, 15, 0.14);
  transition: background var(--t), padding var(--t);
}
.doc-row:hover { background: rgba(22, 20, 15, 0.045); }
.doc-row dt { font-size: 15px; color: rgba(22, 20, 15, 0.66); }
.doc-row dd {
  font-family: var(--mono);
  font-size: 14px;
  letter-spacing: -0.01em;
  text-align: right;
  color: var(--paper-ink);
}
.doc-row.is-lead { padding: 18px 0; }
.doc-row.is-lead dt { font-size: 17px; color: var(--paper-ink); }
.doc-row.is-lead dd { font-size: clamp(24px, 2.6vw, 34px); font-weight: 300; line-height: 1; }

.doc-foot {
  margin-top: 26px;
  padding-top: 18px;
  border-top: 1px solid rgba(22, 20, 15, 0.2);
  max-width: 58ch;
  font-size: 15px;
  color: rgba(22, 20, 15, 0.66);
}

/* ------------------------------------------------------- 06 · finishes */

.finishes { padding-top: clamp(72px, 11vh, 132px); padding-bottom: clamp(64px, 9vh, 110px); }
.finish-list { margin-top: clamp(34px, 5vw, 62px); display: grid; gap: 2px; }

.finish {
  display: grid;
  grid-template-columns: minmax(0, 0.72fr) minmax(0, 1fr);
  gap: clamp(24px, 4vw, 58px);
  align-items: center;
  padding: clamp(24px, 3vw, 40px) clamp(18px, 2.4vw, 34px);
  border: 1px solid var(--line-soft);
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.012);
  transition: background var(--t), border-color var(--t);
}
.finish:hover { background: rgba(255, 255, 255, 0.03); border-color: var(--line); }
.finish.is-chosen { border-color: var(--brass); background: rgba(196, 154, 85, 0.055); }

.finish-plate {
  position: relative;
  aspect-ratio: 16 / 11;
  overflow: hidden;
  border: 1px solid var(--line-soft);
  background: #0d1015;
}
.finish-plate .plate {
  position: absolute;
  width: 150%;
  left: -18%;
  top: 50%;
  transform: translateY(-50%);
  transition: transform var(--t-slow);
}
.finish:hover .finish-plate .plate { transform: translateY(-50%) scale(1.03); }

/* the three surfaces, on the same drawing */
.finish-plate[data-finish='frosted'] .plate {
  --c-line: rgba(214, 224, 236, 0.62);
  --c-fine: rgba(214, 224, 236, 0.3);
}
.finish-plate[data-finish='frosted'] .pl-grain line { stroke: rgba(255, 255, 255, 0.1); }

.finish-plate[data-finish='skeleton'] .plate {
  --face-op: 0.12;
  --c-line: rgba(244, 248, 253, 0.9);
  --c-fine: rgba(244, 248, 253, 0.4);
  width: 210%;
  left: -66%;
}
.finish-plate[data-finish='skeleton'] .pl-bridge { fill: none; stroke: rgba(255, 255, 255, 0.85); stroke-width: 1.6; }
.finish-plate[data-finish='skeleton'] .pl-grain { display: none; }

.finish-plate[data-finish='black'] .plate {
  --c-line: rgba(190, 202, 216, 0.34);
  --c-fine: rgba(190, 202, 216, 0.16);
  width: 190%;
  left: -22%;
}
.finish-plate[data-finish='black'] .pl-bridge {
  fill: #05070a;
  stroke: rgba(255, 255, 255, 0.92);
  stroke-width: 1.4;
}
.finish-plate[data-finish='black'] .pl-grain { display: none; }
.finish-plate[data-finish='black']::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(114deg, transparent 34%, rgba(255, 255, 255, 0.16) 48%, transparent 60%);
  pointer-events: none;
}

.finish-body h3 { font-size: clamp(24px, 2.7vw, 33px); letter-spacing: -0.025em; }
.finish-desc { margin-top: 10px; max-width: 46ch; color: var(--steel); }
.finish-facts {
  margin-top: 24px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, auto));
  gap: 8px 40px;
  align-items: end;
  justify-content: start;
}
.finish-facts dt {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--dim);
  margin-bottom: 6px;
}
.finish-facts dd { font-family: var(--mono); font-size: 13px; color: var(--steel); }
.finish-facts .price { font-size: clamp(21px, 2.1vw, 27px); font-weight: 300; color: var(--silver); letter-spacing: -0.02em; }
.finish-facts .rem { color: var(--ruby); }
.finish-body .btn { margin-top: 26px; }

/* -------------------------------------------------------- 07 · reserve */

.reserve {
  padding-top: clamp(64px, 9vh, 110px);
  padding-bottom: clamp(72px, 10vh, 120px);
  border-top: 1px solid var(--line-soft);
}
.reserve-body {
  margin-top: clamp(32px, 4vw, 56px);
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(0, 1fr);
  gap: clamp(28px, 4vw, 64px);
  align-items: start;
}

.slip {
  position: relative;
  padding: clamp(24px, 3vw, 36px);
  background: linear-gradient(180deg, var(--paper) 0%, var(--paper-2) 100%);
  color: var(--paper-ink);
  border-radius: 1px;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.45);
  min-height: 280px;
}
.slip-kicker {
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--paper-dim);
  padding-bottom: 16px;
  border-bottom: 1px solid rgba(22, 20, 15, 0.2);
}
.slip-finish { margin-top: 22px; font-size: clamp(24px, 2.6vw, 31px); line-height: 1.12; letter-spacing: -0.025em; }
.slip-price { margin-top: 8px; font-family: var(--mono); font-size: clamp(22px, 2.4vw, 30px); font-weight: 300; }
.slip-rows { margin-top: 26px; display: grid; gap: 1px; }
.slip-rows > div {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 11px 0;
  border-top: 1px solid rgba(22, 20, 15, 0.16);
}
.slip-rows dt { font-size: 14px; color: rgba(22, 20, 15, 0.6); }
.slip-rows dd { font-family: var(--mono); font-size: 13px; text-align: right; }
.slip-empty { margin-top: 34px; display: grid; gap: 18px; justify-items: start; color: rgba(22, 20, 15, 0.62); }
.slip-empty .btn { color: var(--paper-ink); border-color: rgba(22, 20, 15, 0.3); }
.slip-empty .btn:hover { background: rgba(22, 20, 15, 0.06); border-color: var(--paper-ink); color: var(--paper-ink); }
.slip-stamp {
  position: absolute;
  right: clamp(18px, 3vw, 34px);
  bottom: clamp(18px, 3vw, 30px);
  font-family: var(--mono);
  font-size: 15px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: rgba(45, 78, 140, 0.85);
  border: 2px solid rgba(45, 78, 140, 0.6);
  border-radius: 2px;
  padding: 6px 14px 6px 18px;
  transform: rotate(-7deg);
}

.field { display: grid; gap: 8px; margin-bottom: 20px; }
.field label {
  font-family: var(--mono);
  font-size: 10.5px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--steel);
}
.field input,
.field select {
  height: 52px;
  padding: 0 14px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--line);
  border-radius: 2px;
  color: var(--silver);
  font-size: 16px;
  transition: border-color var(--t), background var(--t);
}
.field select {
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--steel) 50%), linear-gradient(135deg, var(--steel) 50%, transparent 50%);
  background-position: calc(100% - 20px) 24px, calc(100% - 14px) 24px;
  background-size: 6px 6px, 6px 6px;
  background-repeat: no-repeat;
  cursor: pointer;
}
.field input:hover,
.field select:hover { border-color: var(--line-strong); }
.field input:focus,
.field select:focus { border-color: var(--blued); background: rgba(108, 147, 214, 0.06); outline: none; }
.field option { background: var(--panel); color: var(--silver); }

.form-note {
  margin-bottom: 16px;
  padding: 11px 14px;
  border-left: 2px solid var(--ruby);
  background: rgba(196, 86, 111, 0.08);
  font-size: 15px;
  color: #e2b7c1;
}
.form-fine {
  margin-top: 14px;
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.1em;
  color: var(--dim);
  text-align: center;
}
.confirm {
  padding: 26px 28px;
  border: 1px solid var(--brass);
  border-radius: 2px;
  background: rgba(196, 154, 85, 0.07);
  font-size: clamp(17px, 1.6vw, 21px);
  line-height: 1.55;
}

/* --------------------------------------------------------------- footer */

.foot {
  padding: clamp(40px, 6vh, 68px) var(--gut) 34px;
  padding-left: calc(var(--gut) + var(--rail));
