import { chromium } from 'playwright'
import fs from 'fs'
const url = 'http://localhost:4173/'
fs.mkdirSync('.shots', { recursive: true })
const b = await chromium.launch()
const errs = []
async function open(w, h, name) {
  const p = await b.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 })
  p.on('console', m => { if (m.type() === 'error') errs.push(name + ': ' + m.text()) })
  p.on('pageerror', e => errs.push(name + ': ' + e.message))
  p.on('requestfailed', r => errs.push(name + ' REQFAIL: ' + r.url()))
  await p.goto(url, { waitUntil: 'networkidle' })
  await p.evaluate(async () => {
    await new Promise(r => { let y = 0; const t = setInterval(() => { y += 500; window.scrollTo(0, y); if (y > document.body.scrollHeight) { clearInterval(t); r() } }, 60) })
  })
  await p.waitForTimeout(600)
  return p
}
async function full(p, name) {
  await p.evaluate(() => window.scrollTo(0, 0))
  await p.waitForTimeout(400)
  const info = await p.evaluate(() => {
    const vw = document.documentElement.clientWidth
    const bad = []
    document.querySelectorAll('*').forEach(el => {
      const r = el.getBoundingClientRect()
      if (r.width && (r.right > vw + 1 || r.left < -1)) bad.push((el.className && el.className.baseVal !== undefined ? el.tagName + '.' + el.className.baseVal : el.tagName + '.' + el.className) + ' ' + Math.round(r.left) + '→' + Math.round(r.right))
    })
    return { sw: document.documentElement.scrollWidth, vw, bad: bad.slice(0, 12) }
  })
  console.log(name, JSON.stringify(info))
  await p.screenshot({ path: `.shots/${name}.png`, fullPage: true })
}
const d = await open(1440, 900, 'desktop'); await full(d, 'desktop')
const m = await open(390, 844, 'mobile'); await full(m, 'mobile')
console.log('ERRORS:', errs.length ? errs : 'none')
await b.close()
